35	export interface ScenarioResult {
36	  results: StepResult[];
37	}
38	
39	const PROCESSING_FEE = 5;
40	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
41	
42	const percentOf = (amount: number, percent: number): number =>
43	  (amount * percent) / 100;
44	
45	const quotePremium = (items: Item[]): number => {
46	  const policyBase = items.length * 100;
47	  const surcharge = percentOf(policyBase, FIRST_INSURANCE_SURCHARGE_PERCENT);
48	  return Math.ceil(policyBase + surcharge + PROCESSING_FEE);
49	};
50	
51	export const runScenario = (scenario: Scenario): ScenarioResult => {
52	  return {
53	    results: scenario.steps.map((step) => ({
54	      premium: quotePremium(step.op === "quote" ? step.items : []),
55	    })),
56	  };
57	};
